import pandas as pd
import numpy as np

# Load all experiments and summarize
experiments = {}
for i in range(1, 9):
    df = pd.read_csv(f'experiment_{i}_csv')
    experiments[i] = df
    print(f"\n--- Experiment {i} ---")
    print(f"Columns: {list(df.columns)}")
    print(f"Mean CropYield: {df['CropYield'].mean():.3f}")
    if 'do_iron_fertigation' in df.columns:
        print(f"Iron dose: {df['do_iron_fertigation'].unique()}")
    if 'do_ph_acidifier' in df.columns:
        print(f"pH acidifier: {df['do_ph_acidifier'].unique()}")
    if 'PARLight' in df.columns:
        print(f"PARLight mean: {df['PARLight'].mean():.1f}")
    if 'DissolvedO2Nutrient' in df.columns:
        print(f"DO Nutrient mean: {df['DissolvedO2Nutrient'].mean():.1f}")

# Iron dose-response
print("\n=== Iron Dose Response ===")
iron_data = []
for exp_id, df in experiments.items():
    if 'do_iron_fertigation' in df.columns:
        for dose in df['do_iron_fertigation'].unique():
            subset = df[df['do_iron_fertigation'] == dose]
            iron_data.append({
                'exp': exp_id,
                'iron_dose': dose,
                'mean_yield': subset['CropYield'].mean(),
                'std_yield': subset['CropYield'].std(),
                'n': len(subset)
            })

iron_df = pd.DataFrame(iron_data)
print(iron_df.to_string())

# pH effect
print("\n=== pH Acidifier Effect ===")
for exp_id, df in experiments.items():
    if 'do_ph_acidifier' in df.columns:
        print(f"Exp {exp_id}: pH acidifier={df['do_ph_acidifier'].unique()[0]}, yield={df['CropYield'].mean():.3f}")

import pandas as pd
import os

# List all available experiment files
for i in range(1, 9):
    fname = f"experiment_{i}_csv"
    try:
        df = pd.read_csv(eval(fname))
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(df.columns)}")
        print(f"Shape: {df.shape}")
        # Show unique values for non-numeric, non-unit_id columns
        for col in df.columns:
            if col not in ['unit_id', 'CropYield']:
                if df[col].dtype == 'object':
                    print(f"  {col}: {df[col].unique()}")
                else:
                    print(f"  {col}: mean={df[col].mean():.1f}, unique={df[col].nunique()}")
        print(f"  CropYield: mean={df['CropYield'].mean():.2f}, std={df['CropYield'].std():.2f}")
    except Exception as e:
        print(f"Experiment {i}: ERROR - {e}")

